/**
 * Saves draft `input` for `pageId`, using the pinned owner id in `session`.
 *
 * @param pageId - Stable page ID from source CMS.
 * @param input - Draft content, already schema-validated at the boundary.
 * @param session - Caller session; must carry a resolved owner id.
 * @returns `ok(Draft)` on success, `err({ type: 'stale_revision' })` when `input.baseRevision`
 *   no longer match store's latest revision.
 * @throws {InvariantError} when `session.ownerId` missing — caller bypassed auth middleware.
 */
function saveDraft(
	pageId: string,
	input: DraftInput,
	session: Session,
): Result<Draft, { type: 'stale_revision' }> {
	invariant(session.ownerId !== undefined, 'saveDraft called without resolved ownerId');

	if (input.baseRevision !== store.latestRevision(pageId)) {
		return err({ type: 'stale_revision' });
	}

	return ok(store.write(pageId, input));
}
```

`@throws` mark invariant only (programmer bug, never caller-recoverable). `@returns` name Result's two branch, no restate of type already in signature.

